// ── CONTACT PAGE ────────────────────────────────────────────────────────────
function ContactPage({ data }) {
  const isMobile = true;
  const [form, setForm] = useState({name:"",email:"",message:""});
  const [sent, setSent] = useState(false);
  const [saving, setSaving] = useState(false);
  const [dbLog, setDbLog] = useState([]);

  const handleSend = async () => {
    if (!form.name || !form.email || !form.message) return;
    setSaving(true);
    setDbLog([]);

    // Show live DB log animation
    const logs = [
      { ms: 0,   color:"#6fb3e0", text:`BEGIN;` },
      { ms: 180, color:"#a5d6f5", text:`INSERT INTO contact_messages (name, email, message) VALUES ('${form.name}', '${form.email}', '...');` },
    ];
    logs.forEach(({ ms, color, text }) => {
      setTimeout(() => setDbLog(l => [...l, { color, text }]), ms);
    });

    try {
      const res = await fetch(`${API_BASE}/contact/message`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form),
      });
      const row = await res.json();
      if (res.ok) {
        setDbLog(l => [...l,
          { color:"#4ade80", text:`INSERT 0 1  (id: ${row.id})` },
          { color:"#6fb3e0", text:`COMMIT;` },
          { color:"#a78bfa", text:`NOTIFY contact_received, '{"id": ${row.id}}';` },
        ]);
        setSaving(false);
        setSent(true);
        setForm({name:"",email:"",message:""});
        setTimeout(() => { setSent(false); setDbLog([]); }, 6000);
      } else {
        setDbLog(l => [...l, { color:"#f87171", text:`ERROR: ${row.error}` }]);
        setSaving(false);
      }
    } catch (err) {
      setDbLog(l => [...l, { color:"#f87171", text:`Network error: ${err.message}` }]);
      setSaving(false);
    }
  };
  return (
    <PageWrapper title="Get In Touch" number="05">
      <div style={{
          display:"grid",
          gridTemplateColumns: isMobile ? "1fr" : "1fr 1fr",
          gap: isMobile ? "30px" : "60px",
          alignItems:"start"
        }}>
        <div>
          <p style={{fontSize:"1.05rem",color:"rgba(255,255,255,0.55)",lineHeight:1.8,marginBottom:"40px"}}>
            Open to freelance projects, full-time roles, and collaborations in AI and software development. Let's build something extraordinary together.
          </p> 
        </div>
        <GlassCard>
          {sent ? (
            <div style={{textAlign:"center",padding:"40px 0"}}>
              <div style={{fontSize:"3rem",marginBottom:"16px"}}>✅</div>
              <div style={{fontFamily:"'Manrope',sans-serif",fontWeight:700,fontSize:"1.2rem",color:"#4ade80"}}>Message Saved!</div>
              <p style={{color:"rgba(255,255,255,0.5)",marginTop:"8px",fontSize:"0.9rem"}}>Stored in PostgreSQL · I'll reply soon.</p>
              {dbLog.length > 0 && (
                <div style={{marginTop:"20px",background:"rgba(0,0,0,0.4)",borderRadius:"10px",padding:"14px",textAlign:"left",border:"1px solid rgba(51,103,145,0.3)"}}>
                  <div style={{fontSize:"0.65rem",letterSpacing:"0.1em",textTransform:"uppercase",color:"rgba(111,179,224,0.7)",fontWeight:700,marginBottom:"8px"}}>PostgreSQL Log</div>
                  {dbLog.map((l,i)=>(
                    <div key={i} style={{fontFamily:"monospace",fontSize:"0.72rem",color:l.color,lineHeight:1.8}}>{l.text}</div>
                  ))}
                </div>
              )}
            </div>
          ) : saving ? (
            <div style={{textAlign:"center",padding:"40px 0"}}>
              <div style={{fontSize:"2.5rem",marginBottom:"16px",animation:"blink 0.8s infinite"}}>🐘</div>
              <div style={{fontFamily:"'Manrope',sans-serif",fontWeight:700,fontSize:"1rem",color:"#6fb3e0"}}>Saving to PostgreSQL…</div>
              {dbLog.length > 0 && (
                <div style={{marginTop:"20px",background:"rgba(0,0,0,0.4)",borderRadius:"10px",padding:"14px",textAlign:"left",border:"1px solid rgba(51,103,145,0.3)"}}>
                  {dbLog.map((l,i)=>(
                    <div key={i} style={{fontFamily:"monospace",fontSize:"0.72rem",color:l.color,lineHeight:1.8}}>{l.text}</div>
                  ))}
                </div>
              )}
            </div>
          ) : (
            <div style={{display:"flex",flexDirection:"column",gap:"18px"}}>
              {[["Name","text","Your name",form.name,"name"],["Email","email","Your email",form.email,"email"]].map(([label,type,ph,val,key])=>(
                <div key={key}>
                  <label style={labelStyle}>{label}</label>
                  <input type={type} placeholder={ph} value={val}
                    onChange={e=>setForm(f=>({...f,[key]:e.target.value}))}
                    style={inputStyle} />
                </div>
              ))}
              <div>
                <label style={labelStyle}>Message</label>
                <textarea placeholder="Tell me about your project..." rows={5}
                  value={form.message} onChange={e=>setForm(f=>({...f,message:e.target.value}))}
                  style={{...inputStyle,resize:"vertical"}} />
              </div>
              <button onClick={handleSend} style={{
                ...btnPrimary, padding:"13px", width:"100%",
                boxShadow:"0 0 20px rgba(96,165,250,0.2)",
              }}>Send Message →</button>
            </div>
          )}
        </GlassCard>
          <div
                style={{
                  width: "100%",
                  maxWidth: "700px",
                  margin: "0 auto"
                }}
              >
            {[             
                ["📧","Email",data.email],
                ["💼","LinkedIn",data.linkedin],
                ["🐙","GitHub",data.github],
                ["💬","Twitter",data.twitter],
                ["📍","Location","India — Remote Worldwide"]
                ].map(([icon,label,val],index)=>(
              <div
                    key={label}
                    style={{
                      display:"flex",
                      gap:"16px",
                      alignItems:"center",
                      padding:"18px 0",
                      borderBottom:"1px solid rgba(255,255,255,0.06)",                   
                    }}
                  >
                <span style={{fontSize:"1.2rem",width:"28px"}}>{icon}</span>
                <div>
                  <div style={{fontSize:"0.68rem",letterSpacing:"0.1em",textTransform:"uppercase",
                    color:"rgba(96,165,250,0.6)",fontWeight:700,marginBottom:"2px"}}>{label}</div>
                  <div style={{fontSize:"0.9rem",color:"rgba(255,255,255,0.7)",fontWeight:500}}>{val}</div>
                </div>
              </div>
            ))}
          </div>
      </div>
    </PageWrapper>
  );
}

// ── ADMIN PAGE ──────────────────────────────────────────────────────────────
function AdminPage({ data, setData, reloadData }) {
  const [tab, setTab] = useState("hero");
  const [saved, setSaved] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState(null);
  const [local, setLocal] = useState(JSON.parse(JSON.stringify(data)));

  // Sync when external data changes (e.g. after reload)
  useEffect(() => { setLocal(JSON.parse(JSON.stringify(data))); }, [data]);

  const showSaved = () => { setSaved(true); setTimeout(()=>setSaved(false),2500); };

  // Save ALL sections to PostgreSQL
  const save = async () => {
    setSaving(true); setError(null);
    try {
      await Promise.all([
        fetch(`${API_BASE}/hero`, {
          method:"PUT", headers:{"Content-Type":"application/json"},
          body: JSON.stringify({
            name: local.hero.name, title: local.hero.title,
            subtitle: local.hero.subtitle, tagline: local.hero.tagline,
            available: local.hero.available, photo_b64: local.hero.photo_b64||null,
          }),
        }),
        fetch(`${API_BASE}/about`, {
          method:"PUT", headers:{"Content-Type":"application/json"},
          body: JSON.stringify({
            bio: local.about.bio, bio2: local.about.bio2,
            location: local.about.location, email: local.about.email,
            experience: local.about.experience,
            projects_count: local.about.projects,
            ai_models: local.about.aiModels,
          }),
        }),
        fetch(`${API_BASE}/contact`, {
          method:"PUT", headers:{"Content-Type":"application/json"},
          body: JSON.stringify(local.contact),
        }),
        fetch(`${API_BASE}/resume`, {
          method:"PUT", headers:{"Content-Type":"application/json"},
          body: JSON.stringify({
            file_name: local.resume.fileName, file_data: local.resume.fileData,
            education: local.resume.education, education_years: local.resume.educationYears,
            experience: local.resume.experience, experience_years: local.resume.experienceYears,
            certifications: local.resume.certifications, cert_years: local.resume.certYears,
            open_source: local.resume.openSource, open_source_years: local.resume.openSourceYears,
          }),
        }),
      ]);
      // Reload from DB to confirm persistence
      await reloadData();
      showSaved();
    } catch(e) {
      setError("Save failed: " + e.message);
    } finally {
      setSaving(false);
    }
  };

  const upd = (section, key, val) => setLocal(l=>({...l,[section]:{...l[section],[key]:val}}));

  const tabs = [
    { id:"hero", label:"🏠 Hero" },
    { id:"about", label:"👤 About" },
    { id:"skills", label:"🛠 Skills" },
    { id:"projects", label:"📁 Projects" },
    { id:"contact", label:"📬 Contact" },
    { id:"resume", label:"📄 Resume" },
  ];

  return (
    <PageWrapper title="Admin Panel" number="⚙">
      {/* Tab Bar */}
      <div style={{display:"flex",gap:"8px",marginBottom:"32px",flexWrap:"wrap",alignItems:"center"}}>
        {tabs.map(t=>(
          <button key={t.id} onClick={()=>setTab(t.id)} style={{
            padding:"9px 20px",borderRadius:"9px",border:"1px solid rgba(255,255,255,0.1)",cursor:"pointer",
            background: tab===t.id ? "rgba(96,165,250,0.18)" : "rgba(255,255,255,0.04)",
            color: tab===t.id ? "#60a5fa" : "rgba(255,255,255,0.5)",
            fontFamily:"'Manrope',sans-serif",fontWeight:600,fontSize:"0.82rem",
            borderBottom: tab===t.id ? "1px solid #60a5fa" : "1px solid rgba(255,255,255,0.1)",
            transition:"all 0.2s",
          }}>{t.label}</button>
        ))}
        <button onClick={save} disabled={saving} style={{
          marginLeft:"auto",...btnPrimary,
          background: saved ? "rgba(74,222,128,0.2)" : saving ? "rgba(96,165,250,0.15)" : "linear-gradient(135deg,#2563eb,#7c3aed)",
          color: saved ? "#4ade80" : saving ? "#60a5fa" : "#fff",
          border: saved ? "1px solid rgba(74,222,128,0.4)" : "none",
          padding:"9px 28px", opacity: saving ? 0.7 : 1,
        }}>{saved ? "✓ Saved to PostgreSQL!" : saving ? "Saving…" : "💾 Save All to DB"}</button>
      </div>

      {error && (
        <div style={{padding:"12px 16px",borderRadius:"10px",background:"rgba(248,113,113,0.1)",
          border:"1px solid rgba(248,113,113,0.3)",color:"#f87171",fontSize:"0.85rem",marginBottom:"20px"}}>
          ⚠ {error}
        </div>
      )}

      {/* Tab Content */}
      <div style={{animation:"pageIn 0.3s ease both"}}>
        {tab === "hero"     && <AdminHeroTab local={local} upd={upd} />}
        {tab === "about"    && <AdminAboutTab local={local} upd={upd} />}
        {tab === "skills"   && <AdminSkillsTab local={local} setLocal={setLocal} reloadData={reloadData} />}
        {tab === "projects" && <AdminProjectsTab local={local} setLocal={setLocal} reloadData={reloadData} />}
        {tab === "contact"  && <AdminContactTab local={local} upd={upd} />}
        {tab === "resume"   && <AdminResumeTab local={local} upd={upd} setLocal={setLocal} />}
      </div>

      <div style={{marginTop:"24px",padding:"16px 20px",borderRadius:"12px",
        background:"rgba(51,103,145,0.1)",border:"1px solid rgba(51,103,145,0.3)"}}>
        <span style={{fontSize:"0.8rem",color:"rgba(111,179,224,0.8)",fontWeight:600}}>
          🐘 All changes are persisted to <code style={{color:"#6fb3e0"}}>PostgreSQL</code> via the Express API at <code style={{color:"#6fb3e0"}}>{API_BASE}</code>. Data survives page refresh and server restart.
        </span>
      </div>
    </PageWrapper>
  );
}

