// Admin: Skills Tab (full CRUD → PostgreSQL)
function AdminSkillsTab({ local, setLocal, reloadData }) {
  const [editing, setEditing] = useState(null);
  const [form, setForm] = useState({ icon:"", name:"", desc:"", tags:"" });
  const [adding, setAdding] = useState(false);
  const [busy, setBusy] = useState(false);

  const startEdit = (sk) => {
    setEditing(sk.id); setAdding(false);
    setForm({ icon:sk.icon, name:sk.name, desc:sk.desc, tags:sk.tags.join(", ") });
  };
  const cancelEdit = () => { setEditing(null); setAdding(false); setForm({ icon:"", name:"", desc:"", tags:"" }); };

  const saveEdit = async () => {
    setBusy(true);
    try {
      await fetch(`${API_BASE}/skills/${editing}`, {
        method:"PUT", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({
          icon: form.icon, name: form.name, description: form.desc,
          tags: form.tags.split(",").map(t=>t.trim()).filter(Boolean),
        }),
      });
      await reloadData();
      cancelEdit();
    } finally { setBusy(false); }
  };

  const deleteSkill = async (id) => {
    if (!window.confirm("Delete this skill from PostgreSQL?")) return;
    setBusy(true);
    try {
      await fetch(`${API_BASE}/skills/${id}`, { method:"DELETE" });
      await reloadData();
      if (editing===id) cancelEdit();
    } finally { setBusy(false); }
  };

  const addSkill = async () => {
    if (!form.name.trim()) return;
    setBusy(true);
    try {
      await fetch(`${API_BASE}/skills`, {
        method:"POST", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({
          icon: form.icon||"🔧", name: form.name, description: form.desc,
          tags: form.tags.split(",").map(t=>t.trim()).filter(Boolean),
        }),
      });
      await reloadData();
      cancelEdit();
    } finally { setBusy(false); }
  };

  return (
    <div style={{display:"flex",flexDirection:"column",gap:"12px"}}>
      {busy && <div style={{padding:"8px 16px",borderRadius:"8px",background:"rgba(96,165,250,0.1)",color:"#60a5fa",fontSize:"0.8rem"}}>⏳ Saving to PostgreSQL…</div>}
      {local.skills.map(sk=>(
        <GlassCard key={sk.id} style={{padding:"20px 24px"}}>
          {editing===sk.id ? (
            <SkillForm form={form} setForm={setForm} onSave={saveEdit} onCancel={cancelEdit} saveLabel="Save to DB" />
          ) : (
            <div style={{display:"flex",alignItems:"center",gap:"16px",justifyContent:"space-between",flexWrap:"wrap"}}>
              <div style={{display:"flex",alignItems:"center",gap:"12px"}}>
                <span style={{fontSize:"1.6rem"}}>{sk.icon}</span>
                <div>
                  <div style={{fontWeight:700,color:"#fff",marginBottom:"3px"}}>{sk.name}</div>
                  <div style={{fontSize:"0.78rem",color:"rgba(255,255,255,0.4)",maxWidth:"400px",lineHeight:1.5}}>{sk.desc}</div>
                  <div style={{display:"flex",flexWrap:"wrap",gap:"5px",marginTop:"8px"}}>
                    {sk.tags.map(t=>(
                      <span key={t} style={{padding:"2px 8px",borderRadius:"5px",fontSize:"0.6rem",
                        letterSpacing:"0.06em",textTransform:"uppercase",fontWeight:600,
                        background:"rgba(96,165,250,0.1)",color:"rgba(96,165,250,0.9)"}}>{t}</span>
                    ))}
                  </div>
                </div>
              </div>
              <div style={{display:"flex",gap:"8px"}}>
                <button onClick={()=>startEdit(sk)} style={btnGhost}>✏ Edit</button>
                <button onClick={()=>deleteSkill(sk.id)} style={btnDanger}>🗑 Delete</button>
              </div>
            </div>
          )}
        </GlassCard>
      ))}

      {adding ? (
        <GlassCard style={{border:"1px dashed rgba(96,165,250,0.4)"}}>
          <div style={{fontWeight:700,color:"#60a5fa",marginBottom:"16px",fontSize:"0.9rem"}}>➕ New Skill</div>
          <SkillForm form={form} setForm={setForm} onSave={addSkill} onCancel={cancelEdit} saveLabel="Add to DB" />
        </GlassCard>
      ) : (
        <button onClick={()=>{setAdding(true);setEditing(null);setForm({icon:"",name:"",desc:"",tags:""}); }} style={{
          ...btnPrimary, alignSelf:"flex-start",
        }}>➕ Add New Skill</button>
      )}
    </div>
  );
}

function SkillForm({ form, setForm, onSave, onCancel, saveLabel }) {
  return (
    <div style={{display:"flex",flexDirection:"column",gap:"14px"}}>
      <div style={{display:"grid",gridTemplateColumns:"100px 1fr",gap:"12px"}}>
        <div>
          <label style={labelStyle}>Icon (emoji)</label>
          <input value={form.icon} onChange={e=>setForm(f=>({...f,icon:e.target.value}))} placeholder="🔧" style={inputStyle} />
        </div>
        <div>
          <label style={labelStyle}>Skill Name</label>
          <input value={form.name} onChange={e=>setForm(f=>({...f,name:e.target.value}))} placeholder="e.g. AI & Machine Learning" style={inputStyle} />
        </div>
      </div>
      <div>
        <label style={labelStyle}>Description</label>
        <textarea rows={2} value={form.desc} onChange={e=>setForm(f=>({...f,desc:e.target.value}))} placeholder="Short description..." style={{...inputStyle,resize:"vertical"}} />
      </div>
      <div>
        <label style={labelStyle}>Tags (comma separated)</label>
        <input value={form.tags} onChange={e=>setForm(f=>({...f,tags:e.target.value}))} placeholder="React, Python, FastAPI" style={inputStyle} />
      </div>
      <div style={{display:"flex",gap:"10px"}}>
        <button onClick={onSave} style={btnPrimary}>{saveLabel}</button>
        <button onClick={onCancel} style={{...btnGhost,background:"rgba(255,255,255,0.06)",color:"rgba(255,255,255,0.5)",border:"1px solid rgba(255,255,255,0.1)"}}>Cancel</button>
      </div>
    </div>
  );
}

// Admin: Projects Tab (full CRUD → PostgreSQL)
function AdminProjectsTab({ local, setLocal, reloadData }) {
  const [editing, setEditing] = useState(null);
  const [form, setForm] = useState({ name:"", type:"", year:"", desc:"", tags:"", link:"" });
  const [adding, setAdding] = useState(false);
  const [busy, setBusy] = useState(false);

  const startEdit = (p) => {
    setEditing(p.id); setAdding(false);
    setForm({ name:p.name, type:p.type, year:p.year, desc:p.desc, tags:p.tags.join(", "), link:p.link });
  };
  const cancelEdit = () => { setEditing(null); setAdding(false); setForm({ name:"", type:"", year:"", desc:"", tags:"", link:"" }); };

  const saveEdit = async () => {
    setBusy(true);
    try {
      await fetch(`${API_BASE}/projects/${editing}`, {
        method:"PUT", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({
          name:form.name, type:form.type, year:form.year, description:form.desc,
          tags:form.tags.split(",").map(t=>t.trim()).filter(Boolean), link:form.link,
        }),
      });
      await reloadData();
      cancelEdit();
    } finally { setBusy(false); }
  };

  const deleteProject = async (id) => {
    if (!window.confirm("Delete this project from PostgreSQL?")) return;
    setBusy(true);
    try {
      await fetch(`${API_BASE}/projects/${id}`, { method:"DELETE" });
      await reloadData();
      if (editing===id) cancelEdit();
    } finally { setBusy(false); }
  };

  const addProject = async () => {
    if (!form.name.trim()) return;
    setBusy(true);
    try {
      await fetch(`${API_BASE}/projects`, {
        method:"POST", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({
          name:form.name, type:form.type, year:form.year||new Date().getFullYear().toString(),
          description:form.desc, tags:form.tags.split(",").map(t=>t.trim()).filter(Boolean),
          link:form.link||"#",
        }),
      });
      await reloadData();
      cancelEdit();
    } finally { setBusy(false); }
  };

  return (
    <div style={{display:"flex",flexDirection:"column",gap:"12px"}}>
      {busy && <div style={{padding:"8px 16px",borderRadius:"8px",background:"rgba(96,165,250,0.1)",color:"#60a5fa",fontSize:"0.8rem"}}>⏳ Saving to PostgreSQL…</div>}
      {local.projects.map(p=>(
        <GlassCard key={p.id} style={{padding:"20px 24px"}}>
          {editing===p.id ? (
            <ProjectForm form={form} setForm={setForm} onSave={saveEdit} onCancel={cancelEdit} saveLabel="Save to DB" />
          ) : (
            <div style={{display:"flex",alignItems:"flex-start",gap:"16px",justifyContent:"space-between",flexWrap:"wrap"}}>
              <div style={{display:"flex",gap:"16px",flex:1}}>
                <span style={{fontSize:"0.8rem",color:"rgba(96,165,250,0.6)",fontWeight:700,
                  letterSpacing:"0.1em",minWidth:"28px",paddingTop:"3px"}}>{p.num}</span>
                <div style={{flex:1}}>
                  <div style={{fontWeight:700,color:"#fff",marginBottom:"3px",fontSize:"1.05rem"}}>{p.name}</div>
                  <div style={{fontSize:"0.72rem",letterSpacing:"0.08em",textTransform:"uppercase",
                    color:"rgba(255,255,255,0.3)",marginBottom:"6px"}}>{p.type} · {p.year}</div>
                  <div style={{fontSize:"0.82rem",color:"rgba(255,255,255,0.45)",lineHeight:1.6,marginBottom:"8px"}}>{p.desc}</div>
                  <div style={{display:"flex",flexWrap:"wrap",gap:"5px"}}>
                    {p.tags.map(t=>(
                      <span key={t} style={{padding:"2px 8px",borderRadius:"5px",fontSize:"0.6rem",
                        letterSpacing:"0.06em",textTransform:"uppercase",fontWeight:600,
                        background:"rgba(96,165,250,0.1)",color:"rgba(96,165,250,0.9)"}}>{t}</span>
                    ))}
                  </div>
                </div>
              </div>
              <div style={{display:"flex",gap:"8px",flexShrink:0}}>
                <button onClick={()=>startEdit(p)} style={btnGhost}>✏ Edit</button>
                <button onClick={()=>deleteProject(p.id)} style={btnDanger}>🗑 Delete</button>
              </div>
            </div>
          )}
        </GlassCard>
      ))}

      {adding ? (
        <GlassCard style={{border:"1px dashed rgba(96,165,250,0.4)"}}>
          <div style={{fontWeight:700,color:"#60a5fa",marginBottom:"16px",fontSize:"0.9rem"}}>➕ New Project</div>
          <ProjectForm form={form} setForm={setForm} onSave={addProject} onCancel={cancelEdit} saveLabel="Add to DB" />
        </GlassCard>
      ) : (
        <button onClick={()=>{setAdding(true);setEditing(null);}} style={{...btnPrimary,alignSelf:"flex-start"}}>
          ➕ Add New Project
        </button>
      )}
    </div>
  );
}

function ProjectForm({ form, setForm, onSave, onCancel, saveLabel }) {
  return (
    <div style={{display:"flex",flexDirection:"column",gap:"14px"}}>
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 100px",gap:"12px"}}>
        <div>
          <label style={labelStyle}>Project Name</label>
          <input value={form.name} onChange={e=>setForm(f=>({...f,name:e.target.value}))} placeholder="e.g. AI Document Assistant" style={inputStyle} />
        </div>
        <div>
          <label style={labelStyle}>Type / Category</label>
          <input value={form.type} onChange={e=>setForm(f=>({...f,type:e.target.value}))} placeholder="e.g. AI / Full-Stack" style={inputStyle} />
        </div>
        <div>
          <label style={labelStyle}>Year</label>
          <input value={form.year} onChange={e=>setForm(f=>({...f,year:e.target.value}))} placeholder="2024" style={inputStyle} />
        </div>
      </div>
      <div>
        <label style={labelStyle}>Description</label>
        <textarea rows={3} value={form.desc} onChange={e=>setForm(f=>({...f,desc:e.target.value}))} placeholder="Describe the project..." style={{...inputStyle,resize:"vertical"}} />
      </div>
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:"12px"}}>
        <div>
          <label style={labelStyle}>Tags (comma separated)</label>
          <input value={form.tags} onChange={e=>setForm(f=>({...f,tags:e.target.value}))} placeholder="React, Python, FastAPI" style={inputStyle} />
        </div>
        <div>
          <label style={labelStyle}>Project Link</label>
          <input value={form.link} onChange={e=>setForm(f=>({...f,link:e.target.value}))} placeholder="https://github.com/..." style={inputStyle} />
        </div>
      </div>
      <div style={{display:"flex",gap:"10px"}}>
        <button onClick={onSave} style={btnPrimary}>{saveLabel}</button>
        <button onClick={onCancel} style={{...btnGhost,background:"rgba(255,255,255,0.06)",color:"rgba(255,255,255,0.5)",border:"1px solid rgba(255,255,255,0.1)"}}>Cancel</button>
      </div>
    </div>
  );
}

// Admin: Resume Tab (file upload + info edit)
function AdminResumeTab({ local, upd, setLocal }) {
  const fileRef = useRef(null);
  const [uploading, setUploading] = useState(false);

  const handleFile = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    if (file.size > 5 * 1024 * 1024) { alert("File too large. Max 5MB."); return; }
    setUploading(true);
    const reader = new FileReader();
    reader.onload = (ev) => {
      setLocal(l=>({...l, resume:{...l.resume, fileName:file.name, fileData:ev.target.result}}));
      setUploading(false);
    };
    reader.readAsDataURL(file);
  };

  const removeFile = () => {
    setLocal(l=>({...l, resume:{...l.resume, fileName:"", fileData:null}}));
    if(fileRef.current) fileRef.current.value="";
  };

  return (
    <div style={{display:"flex",flexDirection:"column",gap:"20px"}}>
      {/* File Upload */}
      <GlassCard>
        <div style={{fontFamily:"'Manrope',sans-serif",fontWeight:700,fontSize:"1rem",color:"#fff",marginBottom:"20px"}}>
          📄 Resume File
        </div>
        {local.resume?.fileData ? (
          <div style={{display:"flex",alignItems:"center",gap:"16px",padding:"16px",borderRadius:"10px",
            background:"rgba(74,222,128,0.07)",border:"1px solid rgba(74,222,128,0.2)"}}>
            <span style={{fontSize:"1.5rem"}}>📎</span>
            <div style={{flex:1}}>
              <div style={{fontWeight:600,color:"#fff",marginBottom:"2px"}}>{local.resume.fileName}</div>
              <div style={{fontSize:"0.75rem",color:"#4ade80"}}>File uploaded successfully</div>
            </div>
            <div style={{display:"flex",gap:"8px"}}>
              <a href={local.resume.fileData} download={local.resume.fileName}
                style={{...btnGhost,textDecoration:"none",padding:"7px 14px"}}>⬇ Preview</a>
              <button onClick={removeFile} style={btnDanger}>🗑 Remove</button>
            </div>
          </div>
        ) : (
          <div onClick={()=>fileRef.current?.click()} style={{
            padding:"40px",borderRadius:"12px",border:"2px dashed rgba(96,165,250,0.3)",
            textAlign:"center",cursor:"pointer",transition:"all 0.2s",
            background:"rgba(96,165,250,0.03)",
          }}>
            <div style={{fontSize:"2.5rem",marginBottom:"12px"}}>{uploading?"⏳":"📤"}</div>
            <div style={{fontWeight:600,color:"rgba(255,255,255,0.7)",marginBottom:"6px"}}>
              {uploading ? "Uploading..." : "Click to upload resume PDF"}
            </div>
            <div style={{fontSize:"0.75rem",color:"rgba(255,255,255,0.3)"}}>PDF, max 5MB</div>
          </div>
        )}
        <input ref={fileRef} type="file" accept=".pdf" onChange={handleFile} style={{display:"none"}} />
      </GlassCard>

      {/* Resume Details */}
      <GlassCard>
        <div style={{fontFamily:"'Manrope',sans-serif",fontWeight:700,fontSize:"1rem",color:"#fff",marginBottom:"20px"}}>
          📋 Resume Details
        </div>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:"16px"}}>
          {[
            ["education","Education",local.resume?.education||""],
            ["educationYears","Education Years",local.resume?.educationYears||""],
            ["experience","Experience",local.resume?.experience||""],
            ["experienceYears","Experience Years",local.resume?.experienceYears||""],
            ["certifications","Certifications",local.resume?.certifications||""],
            ["certYears","Cert. Years",local.resume?.certYears||""],
            ["openSource","Open Source",local.resume?.openSource||""],
            ["openSourceYears","Open Source Years",local.resume?.openSourceYears||""],
          ].map(([key,label,val])=>(
            <div key={key}>
              <label style={labelStyle}>{label}</label>
              <input value={val} onChange={e=>upd("resume",key,e.target.value)} style={inputStyle} />
            </div>
          ))}
        </div>
      </GlassCard>
    </div>
  );
}

