// ── SHARED: AdminFields ──────────────────────────────────────────────────────
function AdminFields({ fields }) {
  return (
    <div style={{display:"flex",flexDirection:"column",gap:"18px"}}>
      {fields.map(([key,label,val,onChange,multiline])=>(
        <div key={key}>
          <label style={labelStyle}>{label}</label>
          {multiline ? (
            <textarea rows={4} value={val} onChange={e=>onChange(e.target.value)} style={{...inputStyle,resize:"vertical"}} />
          ) : (
            <input type="text" value={val} onChange={e=>onChange(e.target.value)} style={inputStyle} />
          )}
        </div>
      ))}
    </div>
  );
}

// ── SHARED: GlassCard & PageWrapper ─────────────────────────────────────────
function GlassCard({ children, hover, style }) {
  const [hovered, setHovered] = useState(false);
  return (
    <div onMouseEnter={()=>hover&&setHovered(true)} onMouseLeave={()=>setHovered(false)}
      style={{
        padding:"28px 30px",borderRadius:"16px",
        background: hovered ? "rgba(96,165,250,0.07)" : "rgba(255,255,255,0.04)",
        border:`1px solid ${hovered ? "rgba(96,165,250,0.25)" : "rgba(255,255,255,0.07)"}`,
        backdropFilter:"blur(20px)",
        transition:"all 0.3s",
        transform: hovered ? "translateY(-4px)" : "none",
        boxShadow: hovered ? "0 20px 60px rgba(0,0,0,0.4)" : "none",
        ...style,
      }}>
      {children}
    </div>
  );
}

function PageWrapper({ title, number, children }) {
  return (
    <div style={{minHeight:"100vh",padding:"100px 60px 80px",maxWidth:"1100px",margin:"0 auto",
      animation:"pageIn 0.4s ease both"}}>
      <div style={{marginBottom:"64px"}}>
        <div style={{fontSize:"0.7rem",letterSpacing:"0.2em",textTransform:"uppercase",
          color:"rgba(96,165,250,0.6)",fontWeight:700,marginBottom:"12px",
          fontFamily:"'Manrope',sans-serif"}}>
          {number} ──────
        </div>
        <h2 style={{fontFamily:"'Manrope',sans-serif",fontWeight:800,
          fontSize:"clamp(32px,5vw,60px)",lineHeight:1.1,letterSpacing:"-0.03em",
          background:"linear-gradient(135deg,#fff 0%,#94a3b8 100%)",
          WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent",margin:0}}>
          {title}
        </h2>
      </div>
      {children}
    </div>
  );
}

// ── LOGIN MODAL ──────────────────────────────────────────────────────────────
function LoginModal({ onLogin, onClose }) {
  const [pw, setPw] = useState("");
  const [err, setErr] = useState(false);
  const attempt = () => {
    if (pw === ADMIN_PASSWORD) { onLogin(); }
    else { setErr(true); setTimeout(()=>setErr(false),2000); }
  };
  return (
    <div style={{position:"fixed",inset:0,zIndex:2000,display:"flex",alignItems:"center",justifyContent:"center",
      background:"rgba(0,0,0,0.8)",backdropFilter:"blur(20px)"}} onClick={onClose}>
      <div onClick={e=>e.stopPropagation()} style={{
        padding:"40px",borderRadius:"20px",width:"380px",
        background:"rgba(15,15,25,0.97)",border:"1px solid rgba(96,165,250,0.2)",
        boxShadow:"0 0 60px rgba(96,165,250,0.1)",animation:"fadeUp 0.3s ease both",
      }}>
        <div style={{fontFamily:"'Manrope',sans-serif",fontWeight:800,fontSize:"1.3rem",color:"#fff",marginBottom:"8px"}}>
          🔐 Admin Login
        </div>
        <p style={{fontSize:"0.85rem",color:"rgba(255,255,255,0.4)",marginBottom:"24px"}}>
          Enter your password to access the admin panel.
        </p>
        <input type="password" placeholder="Password" value={pw}
          onChange={e=>setPw(e.target.value)} onKeyDown={e=>e.key==="Enter"&&attempt()}
          style={{...inputStyle, marginBottom:"12px",
            border:`1px solid ${err?"#f87171":"rgba(255,255,255,0.12)"}`}} />
        {err && <div style={{fontSize:"0.8rem",color:"#f87171",marginBottom:"12px"}}>❌ Incorrect password</div>}
        <button onClick={attempt} style={{...btnPrimary, width:"100%", padding:"12px"}}>
          Enter Admin Panel →
        </button>
      </div>
    </div>
  );
}

// ── MAIN APP ─────────────────────────────────────────────────────────────────
export default function App() {
  const [page, setPage] = useState("Hero");
  const [data, setData] = useState(EMPTY_DATA);
  const [loading, setLoading] = useState(true);
  const [dbError, setDbError] = useState(null);
  const [isAdmin, setIsAdmin] = useState(false);
  const [showLogin, setShowLogin] = useState(false);
  const [prevPage, setPrevPage] = useState("Hero");

  // ── Load ALL data from PostgreSQL on mount and after saves ─────────────────
  const reloadData = useCallback(async () => {
    try {
      const res = await fetch(`${API_BASE}/portfolio`);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const raw = await res.json();
      setData({
        hero:     mapHero(raw.hero     || {}),
        about:    mapAbout(raw.about   || {}),
        skills:   (raw.skills   || []).map(mapSkill),
        projects: (raw.projects || []).map(mapProject),
        resume:   mapResume(raw.resume  || {}),
        contact:  mapContact(raw.contact || {}),
      });
      setDbError(null);
    } catch (e) {
      setDbError(e.message);
    }
  }, []);

  useEffect(() => {
    (async () => {
      await reloadData();
      setLoading(false);
    })();
  }, [reloadData]);

  const handleSetPage = (p) => {
    setPrevPage(page);
    setPage(p);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const handleLogout = () => {
    setIsAdmin(false);
    handleSetPage("Hero");
  };

  const renderPage = () => {
    if (loading) return (
      <div style={{minHeight:"100vh",display:"flex",alignItems:"center",justifyContent:"center",flexDirection:"column",gap:"20px"}}>
        <div style={{fontSize:"3rem",animation:"blink 1s infinite"}}>🐘</div>
        <div style={{fontFamily:"'Manrope',sans-serif",fontWeight:600,fontSize:"1rem",color:"rgba(96,165,250,0.8)"}}>Connecting to PostgreSQL…</div>
      </div>
    );
    if (dbError) return (
      <div style={{minHeight:"100vh",display:"flex",alignItems:"center",justifyContent:"center",flexDirection:"column",gap:"16px",padding:"40px"}}>
        <div style={{fontSize:"3rem"}}>⚠️</div>
        <div style={{fontFamily:"'Manrope',sans-serif",fontWeight:700,fontSize:"1.2rem",color:"#f87171"}}>Cannot connect to PostgreSQL</div>
        <div style={{fontFamily:"monospace",fontSize:"0.85rem",color:"rgba(255,255,255,0.4)",maxWidth:"500px",textAlign:"center"}}>{dbError}</div>
        <div style={{fontSize:"0.85rem",color:"rgba(255,255,255,0.4)",maxWidth:"500px",textAlign:"center"}}>
          Make sure the backend is running at <code style={{color:"#60a5fa"}}>{API_BASE}</code> and PostgreSQL is accessible. See README.md for setup.
        </div>
        <button onClick={reloadData} style={{...btnPrimary,marginTop:"8px"}}>Retry Connection</button>
      </div>
    );

    switch(page) {
      case "Hero":     return <HeroPage data={data.hero} setPage={handleSetPage} />;
      case "About":    return <AboutPage data={data.about} />;
      case "Skills":   return <SkillsPage data={data.skills} />;
      case "Projects": return <ProjectsPage data={data.projects} />;
      case "Resume":   return <ResumePage data={data.resume} />;
      case "Contact": return <ContactPage data={data.contact} />;
      case "admin":    return isAdmin
        ? <AdminPage data={data} setData={setData} reloadData={reloadData} />
        : <HeroPage data={data.hero} setPage={handleSetPage} />;
      default:         return <HeroPage data={data.hero} setPage={handleSetPage} />;
    }
  };

  return (
    <div style={{
      minHeight:"100vh",
      background:"linear-gradient(135deg,#020308 0%,#050510 40%,#080818 70%,#030308 100%)",
      color:"#fff",
      fontFamily:"'Manrope',sans-serif",
      position:"relative",
      overflow:"hidden",
    }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Manrope:wght@300;400;500;600;700;800&display=swap');
        * { box-sizing: border-box; margin: 0; padding: 0; }
        @keyframes fadeUp { from{opacity:0;transform:translateY(24px)} to{opacity:1;transform:none} }
        @keyframes fadeDown { from{opacity:0;transform:translateY(-16px)} to{opacity:1;transform:none} }
        @keyframes blink { 0%,100%{opacity:1} 50%{opacity:0} }
        @keyframes pageIn { from{opacity:0;transform:translateY(16px)} to{opacity:1;transform:none} }
        @keyframes meshMove1 { from{transform:translate(0,0)} to{transform:translate(5%,5%)} }
        @keyframes meshMove2 { from{transform:translate(0,0)} to{transform:translate(-5%,-5%)} }
        input,textarea,button { font-family:'Manrope',sans-serif; }
        input:focus, textarea:focus { border-color: rgba(96,165,250,0.5) !important; outline:none; }
        ::-webkit-scrollbar { width:4px; }
        ::-webkit-scrollbar-track { background:transparent; }
        ::-webkit-scrollbar-thumb { background:rgba(96,165,250,0.3); border-radius:2px; }
      `}</style>

      {/* Mesh background */}
      <div style={{position:"fixed",inset:0,zIndex:0,pointerEvents:"none",overflow:"hidden"}}>
        <div style={{position:"absolute",top:"-20%",left:"-10%",width:"60%",height:"60%",
          background:"radial-gradient(ellipse,rgba(37,99,235,0.08) 0%,transparent 70%)",
          animation:"meshMove1 12s ease-in-out infinite alternate"}} />
        <div style={{position:"absolute",bottom:"-20%",right:"-10%",width:"55%",height:"55%",
          background:"radial-gradient(ellipse,rgba(124,58,237,0.07) 0%,transparent 70%)",
          animation:"meshMove2 15s ease-in-out infinite alternate"}} />
      </div>

      <Particles />

      <div style={{position:"relative",zIndex:1}}>
        <Nav
          page={page}
          setPage={handleSetPage}
          isAdmin={isAdmin}
          setShowLogin={setShowLogin}
          onLogout={handleLogout}
          heroPhoto={data.hero?.photo_b64}
        />
        <div key={page} style={{animation:"pageIn 0.4s ease both"}}>
          {renderPage()}
        </div>
        <footer style={{textAlign:"center",padding:"32px",
          borderTop:"1px solid rgba(255,255,255,0.06)",
          color:"rgba(255,255,255,0.25)",fontSize:"0.75rem",letterSpacing:"0.08em"}}>
          © 2025 Dinesh Yadav · Built with React + Express + PostgreSQL
        </footer>
      </div>

      {showLogin && (
        <LoginModal
          onLogin={()=>{ setIsAdmin(true); setShowLogin(false); handleSetPage("admin"); }}
          onClose={()=>setShowLogin(false)}
        />
      )}
    </div>
  );
}
